/* @component: .slider-full */
(function() {
  const libs = {
    swiper: { js: 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js', css: 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css' },
    plyr: { js: 'https://cdn.plyr.io/3.7.8/plyr.js', css: 'https://cdn.plyr.io/3.7.8/plyr.css' }
  };

  const loadLib = (id, js, css, cb) => {
    if (!document.getElementById(id)) {
      const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = css; document.head.appendChild(l);
      const s = document.createElement('script'); s.id = id; s.src = js; s.onload = cb; document.head.appendChild(s);
    } else { cb(); }
  };

  const init = () => {
    const swipers = document.querySelectorAll('.sliderFull');
    swipers.forEach(s => {
      if (!s.swiper) {
        new Swiper(s, {
          slidesPerView: 1, spaceBetween: 20,
          loop: true, observer: true, observeParents: true,
          pagination: { el: '.swiper-pagination', clickable: true },
          navigation: { nextEl: '.swiper-button-next', prevEl: '.swiper-button-prev' },
          breakpoints: { 768: { slidesPerView: 2 }, 1200: { slidesPerView: 3 } }
        });
      }
    });

    // Задержка, чтобы Swiper успел создать клоны слайдов (loop mode)
    setTimeout(() => {
      const videos = document.querySelectorAll('.slide-player');
      videos.forEach(v => {
        // Инициализируем Plyr только если он еще не создан на этом элементе
        if (v && !v.plyr && !v.closest('.plyr')) {
           new Plyr(v, {
             autoplay: false,
             controls: ['play-large', 'play', 'progress', 'current-time', 'mute', 'volume', 'fullscreen']
           });
        }
      });
    }, 500);
  };

  loadLib('swiper-full-v11', libs.swiper.js, libs.swiper.css, () => {
    loadLib('plyr-full-v3', libs.plyr.js, libs.plyr.css, () => setTimeout(init, 300));
  });
})();
